// Generated by theorem-harness-package from theorem-harness-core. Do not edit:
// `scripts/check-harness-package.sh` reports any difference as drift.
//
// The one way this package reaches native Theorem: JSON-RPC against the
// configured MCP endpoint, plus GET for the few routes `tool-routes.json`
// marks `http`. There is no local fallback; a missing endpoint or a failed
// call is returned as a typed degraded answer.

const URL_ENV = [
  "THEOREMS_HARNESS_MCP_URL",
  "THEOREM_HARNESS_MCP_URL",
  "THEOREM_MCP_URL",
  "THEOREMS_HARNESS_REMOTE_URL",
  "THEOREM_HARNESS_REMOTE_URL",
  "THEOREM_REMOTE_URL",
  "RUSTYRED_THG_MCP_URL",
];
const HTTP_URL_ENV = ["THEOREMS_HARNESS_HTTP_URL", "THEOREM_HARNESS_HTTP_URL"];
// Native HTTP routes take the tenant as a query parameter.
const TENANT_ENV = [
  "THEOREM_HARNESS_TENANT",
  "THEOREMS_HARNESS_TENANT",
  "THEOREM_TENANT_SLUG",
  "THEOREM_HARNESS_TENANT_SLUG",
  "RUSTYRED_THG_TENANT",
];
const TOKEN_ENV = [
  "THEOREM_API_TOKEN",
  "THEOREM_HARNESS_API_TOKEN",
  "THEOREMS_HARNESS_REMOTE_TOKEN",
  "THEOREM_HARNESS_REMOTE_TOKEN",
];

function firstEnv(names, env) {
  for (const name of names) {
    const value = String(env[name] ?? "").trim();
    if (value) return value;
  }
  return "";
}

export function nativeEndpoint(env = process.env) {
  const url = firstEnv(URL_ENV, env);
  if (!url) return "";
  return /\/mcp\/?$/.test(url) ? url : `${url.replace(/\/+$/, "")}/mcp`;
}

// Base URL for native HTTP routes: explicit, else the MCP endpoint's origin.
export function nativeHttpBase(env = process.env) {
  const explicit = firstEnv(HTTP_URL_ENV, env);
  if (explicit) return explicit.replace(/\/+$/, "");
  return nativeEndpoint(env).replace(/\/mcp\/?$/, "");
}

function headers(env, accept) {
  const out = { accept };
  const token = firstEnv(TOKEN_ENV, env);
  if (token) out.authorization = `Bearer ${token}`;
  return out;
}

async function request(url, init, label, timeoutMs, allowEmpty = false) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, { ...init, signal: controller.signal });
    const body = parseBody(await response.text());
    if (!response.ok || (!body && !allowEmpty)) {
      return { ok: false, reason: "http_error", message: `${label}: HTTP ${response.status}`, httpStatus: response.status };
    }
    return { ok: true, body, responseHeaders: response.headers };
  } catch (error) {
    const reason = error?.name === "AbortError" ? "timeout" : "unreachable";
    return { ok: false, reason, message: `${label}: ${reason}` };
  } finally {
    clearTimeout(timer);
  }
}

// A session belongs to one endpoint and credential. Share the initialization
// promise so simultaneous tool discovery/calls cannot race the handshake.
const sessions = new Map();
const PROTOCOL_VERSION = "2025-03-26";

function post(method, params, env, session, notification = false) {
  return {
    method: "POST",
    headers: {
      ...headers(env, "application/json, text/event-stream"),
      "content-type": "application/json",
      ...(session?.id ? { "mcp-session-id": session.id } : {}),
      ...(session ? { "mcp-protocol-version": session.protocolVersion } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", ...(notification ? {} : { id: method }), method, params }),
  };
}

async function initialize(endpoint, env, timeoutMs) {
  const answer = await request(endpoint, post("initialize", {
    protocolVersion: PROTOCOL_VERSION,
    capabilities: {},
    clientInfo: { name: "theorems-harness-host", version: "1.0.0" },
  }, env), "initialize", timeoutMs);
  if (!answer.ok) return answer;
  if (answer.body.error || !answer.body.result?.protocolVersion) {
    return { ok: false, reason: "rpc_error", message: "initialize: native server refused the MCP handshake" };
  }
  const session = {
    id: answer.responseHeaders.get("mcp-session-id"),
    protocolVersion: answer.body.result.protocolVersion,
  };
  const initialized = await request(endpoint, post("notifications/initialized", {}, env, session, true),
    "notifications/initialized", timeoutMs, true);
  return initialized.ok ? { ok: true, session } : initialized;
}

// One JSON-RPC request. Resolves to `{ ok, result }` or
// `{ ok: false, reason, message }`; it never throws.
export async function rpc(method, params = {}, { env = process.env, timeoutMs = 8000 } = {}) {
  const endpoint = nativeEndpoint(env);
  if (!endpoint) {
    return { ok: false, reason: "endpoint_unconfigured", message: `set ${URL_ENV[0]}` };
  }
  const key = JSON.stringify([endpoint, firstEnv(TOKEN_ENV, env)]);
  if (!sessions.has(key)) sessions.set(key, initialize(endpoint, env, timeoutMs));
  const initialization = sessions.get(key);
  const invalidate = () => {
    if (sessions.get(key) === initialization) sessions.delete(key);
  };
  const ready = await initialization;
  if (!ready.ok) {
    invalidate();
    return ready;
  }
  const answer = await request(
    endpoint,
    post(method, params, env, ready.session),
    method,
    timeoutMs,
  );
  if (!answer.ok) {
    // A stale session is discarded for the next call. This call may have
    // effects, so it is never automatically replayed after a handshake.
    if (answer.httpStatus === 404) invalidate();
    return answer;
  }
  if (answer.body.error) {
    const { message, code } = answer.body.error;
    if (["mcp_session_uninitialized", "mcp_session_not_found"].includes(answer.body.error.data?.code)) invalidate();
    return { ok: false, reason: "rpc_error", message: `${method}: ${message ?? code}` };
  }
  return { ok: true, result: answer.body.result ?? {} };
}

// Calls one native tool. Resolves to `{ ok, content, meta, result }` or
// `{ ok: false, reason, message }`; it never throws.
export async function callTool(name, args = {}, options = {}) {
  const answer = await rpc("tools/call", { name, arguments: args }, options);
  if (!answer.ok) return { ...answer, message: `${name}: ${answer.message}` };
  const { result } = answer;
  const content = structured(result);
  if (result.isError) {
    const message = `${name}: ${content.message ?? content.error ?? "error"}`;
    return { ok: false, reason: content.error ?? "tool_error", message, content, result };
  }
  return { ok: true, content, meta: result._meta ?? {}, result };
}

// GETs a native HTTP route. Resolves to `{ ok, body }` or a degraded answer.
export async function getRoute(path, query = {}, { env = process.env, timeoutMs = 8000 } = {}) {
  const base = nativeHttpBase(env);
  if (!base) {
    return { ok: false, reason: "endpoint_unconfigured", message: `set ${HTTP_URL_ENV[0]} or ${URL_ENV[0]}` };
  }
  const url = new URL(`${base}${path}`);
  const tenant = firstEnv(TENANT_ENV, env);
  const params = query.tenant || query.tenant_slug || !tenant ? query : { ...query, tenant };
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== null && value !== "") url.searchParams.set(key, String(value));
  }
  return request(url, { method: "GET", headers: headers(env, "application/json") }, path, timeoutMs);
}

// A tool answers in `structuredContent`, or as JSON in its first text block.
function structured(result) {
  if (result.structuredContent) return result.structuredContent;
  const text = result.content?.find((item) => item.type === "text")?.text;
  if (!text) return {};
  try {
    return JSON.parse(text);
  } catch {
    return { text };
  }
}

// Ordinary HTTP routes return their complete JSON body. MCP may answer with
// SSE keepalives/notifications before its result frame.
function parseBody(text) {
  try {
    return JSON.parse(text);
  } catch {
    // A streamable MCP response is framed as SSE rather than raw JSON.
  }
  const frames = text.split(/\r?\n\r?\n/)
    .map((frame) => frame.split(/\r?\n/).filter((line) => line.startsWith("data:"))
      .map((line) => line.slice(5).trimStart()).join("\n"));
  for (const frame of frames) {
    try {
      const value = JSON.parse(frame);
      if (Object.hasOwn(value, "result") || Object.hasOwn(value, "error")) return value;
    } catch {
      // Ignore SSE keepalives and notification frames.
    }
  }
  return null;
}
